","/* =================================================================
 What-If Planner — Styles
 Prefix: .wf-
 ================================================================= */

/* ---- Shell & Header ---- */
.wf-shell {
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
 min-height: 100vh;
 margin: 0;
 padding: 0;
}

.wf-header {
 background: rgb(var(--now-color_background--secondary, 245, 245, 245));
 border-bottom: 1px solid rgb(var(--now-container--border-color, 218, 220, 224));
 padding: var(--now-static-space--lg, 24px) var(--now-static-space--lg, 24px) var(--now-static-space--md, 16px);
}

.wf-header-title {
 margin: 0 0 var(--now-static-space--xxs, 4px) 0;
 font-size: var(--now-static-font-size--lg, 20px);
 font-weight: 600;
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
}

.wf-header-sub {
 margin: 0;
 font-size: var(--now-static-font-size--sm, 12px);
 color: rgb(var(--now-color_text--secondary, 100, 106, 124));
 letter-spacing: 0.03em;
}

/* ---- Content wrapper ---- */
.wf-content {
 max-width: 1100px;
 margin: 0 auto;
 padding: var(--now-static-space--lg, 24px);
}

/* ---- Section headings ---- */
.wf-section-title {
 font-size: 16px;
 font-weight: 600;
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
 margin: var(--now-static-space--lg, 24px) 0 var(--now-static-space--sm, 8px) 0;
 padding-bottom: var(--now-static-space--xs, 6px);
 border-bottom: 2px solid rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}

/* ---- Summary cards grid ---- */
.wf-cards {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
 gap: var(--now-static-space--md, 16px);
 margin-bottom: var(--now-static-space--lg, 24px);
}

.wf-card {
 background: rgb(var(--now-container--color, 255, 255, 255));
 border: 1px solid rgb(var(--now-container--border-color, 218, 220, 224));
 border-radius: 8px;
 padding: var(--now-static-space--md, 16px);
 text-align: center;
}

.wf-card-value {
 font-size: 28px;
 font-weight: 700;
 color: rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
}

.wf-card-label {
 font-size: var(--now-static-font-size--sm, 12px);
 color: rgb(var(--now-color_text--secondary, 100, 106, 124));
 margin-top: var(--now-static-space--xxs, 4px);
 text-transform: uppercase;
 letter-spacing: 0.04em;
}

/* ---- Scenario builder form ---- */
.wf-form {
 background: rgb(var(--now-container--color, 255, 255, 255));
 border: 1px solid rgb(var(--now-container--border-color, 218, 220, 224));
 border-radius: 8px;
 padding: var(--now-static-space--md, 16px);
 margin-bottom: var(--now-static-space--lg, 24px);
}

.wf-form-field {
 margin-bottom: var(--now-static-space--sm, 8px);
}

.wf-form-field label {
 display: block;
 font-size: var(--now-static-font-size--sm, 12px);
 font-weight: 600;
 color: rgb(var(--now-color_text--secondary, 100, 106, 124));
 margin-bottom: var(--now-static-space--xxs, 4px);
 text-transform: uppercase;
 letter-spacing: 0.03em;
}

.wf-input {
 display: block;
 width: 100%;
 max-width: 440px;
 padding: var(--now-static-space--xs, 6px) var(--now-static-space--sm, 8px);
 font-family: var(--now-font-family, "Source Sans Pro", Arial, sans-serif);
 font-size: 14px;
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
 background: rgb(var(--now-color_background--primary, 255, 255, 255));
 border: 1px solid rgb(var(--now-container--border-color, 218, 220, 224));
 border-radius: 4px;
 box-sizing: border-box;
 appearance: auto;
}

.wf-input:focus {
 outline: 2px solid rgb(var(--now-actionable--primary--background-color, 0, 128, 163));
 outline-offset: -1px;
}

.wf-btn-row {
 margin-top: var(--now-static-space--md, 16px);
}

/* ---- Results container ---- */
.wf-results {
 margin-top: var(--now-static-space--md, 16px);
}

/* ---- Simulation warning banner ---- */
.wf-sim-banner {
 background: #fff3cd;
 color: #664d03;
 border: 2px solid #ffca2c;
 border-radius: 8px;
 padding: var(--now-static-space--sm, 8px) var(--now-static-space--md, 16px);
 font-size: 15px;
 font-weight: 700;
 text-align: center;
 margin-bottom: var(--now-static-space--md, 16px);
}

/* ---- Scenario description ---- */
.wf-scenario-desc {
 font-size: 14px;
 color: rgb(var(--now-color_text--primary, 22, 27, 28));
 margin-bottom: var(--now-static-space--xs, 6px);
}

/* ---- Timestamp ---- */
.wf-timestamp {
 font-size: var(--now-static-font-size--sm, 12px);
 color: rgb(var(--now-color_text--secondary, 100, 106, 124));
 text-align: right;
 margin-bottom: var(--now-static-space--sm, 8px);
}

/* ---- Impact summary grid ---- */
.wf-impact-grid {
 display: grid;
 grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
 gap: var(--now-static-space--md, 16px);
 margin-bottom: var(--now-static-space--lg, 24px);
}

.wf-impact-item {
 background: #fff8e1;
 border: 1px solid #ffca2c;
 border-radius: 8px;
 padding: var(--now-static-space--md, 16px);
 text-align: center;
}

.wf-impact-item .wf-card-value {
 color: #664d03;
}

/* ---- Comparison / data table ---- */
.wf-table {
 width: 100%;
 border-collapse: collapse;
 margin-bottom: var(--now-static-space--lg, 24px);
 font-size: 14px;
}

.wf-table th,
.wf-table td {
 padding: var(--now-static-space--xs, 6px) var(--now-static-space--sm, 8px);
 border: 1px solid rgb(var(--now-container--border-color, 218, 220, 224));
 text-align: left;
}

.wf-table th {
 background: rgb(var(--now-color_background--secondary, 245, 245, 245));
 font-weight: 600;
 font-size: var(--now-static-font-size--sm, 12px);
 color: rgb(var(--now-color_text--secondary, 100, 106, 124));
 text-transform: uppercase;
 letter-spacing: 0.03em;
}

.wf-table tbody tr:nth-child(even) {
 background: rgba(var(--now-color_background--secondary, 245, 245, 245), 0.5);
}

/* ---- Badges (delay indicators) ---- */
.wf-badge {
 display: inline-block;
 padding: 2px 10px;
 border-radius: 10px;
 font-size: var(--now-static-font-size--sm, 12px);
 font-weight: 600;
 white-space: nowrap;
}

.wf-badge-warn {
 background: #fff3cd;
 color: #664d03;
}

.wf-badge-ok {
 background: #d1e7dd;
 color: #0f5132;
}

/* ---- Simulation footer disclaimer ---- */
.wf-sim-footer {
 text-align: center;
 font-size: var(--now-static-font-size--sm, 12px);
 color: rgb(var(--now-color_text--secondary, 100, 106, 124));
 padding: var(--now-static-space--md, 16px) 0;
 border-top: 1px dashed rgb(var(--now-container--border-color, 218, 220, 224));
 margin-top: var(--now-static-space--sm, 8px);
}

/* ---- State: loading ---- */
.wf-loading {
 text-align: center;
 padding: var(--now-static-space--lg, 24px);
 color: rgb(var(--now-color_text--secondary, 100, 106, 124));
