}

/* ---- State: error ---- */
.wf-error {
 background: #f8d7da;
 color: #842029;
 border: 1px solid #f5c2c7;
 border-radius: 8px;
 padding: var(--now-static-space--sm, 8px) var(--now-static-space--md, 16px);
