 border: 1px dashed rgb(var(--now-container--border-color, 218, 220, 224));
 border-radius: 8px;
 color: rgb(var(--now-color_text--secondary, 100, 106, 124));
 font-size: 15px;
 line-height: 1.6;
}

/* ---- Table overflow wrapper ---- */
.wf-table-wrap {
 overflow-x: auto;
 margin-bottom: var(--now-static-space--md, 16px);
}

