.wf-detail-reasons {
 margin-bottom: var(--now-static-space--lg, 24px);
}

.wf-reason-row {
 padding: var(--now-static-space--xs, 6px) var(--now-static-space--sm, 8px);
 font-size: 13px;
 background: #fde2e6;
 color: #b30317;
 border-radius: 4px;
 margin-bottom: var(--now-static-space--xs, 6px);
}
","export default function insertStyle(css, tagName = "style") {
 if (!css || typeof window === "undefined")
 return;
 if (tagName === "style") {
 const style = document.createElement("style");
 style.setAttribute("type", "text/css");
 style.innerHTML = css;
 document.head.appendChild(style);
 }
 else if (tagName === "link") {
 const link = document.createElement("link");
 link.setAttribute("rel", "stylesheet");
 link.setAttribute("href", css);
 document.head.appendChild(link);
 }
 return css;
}","import React, { useState, useEffect } from "react";
import { Button } from "@servicenow/react-components/Button";
import "./styles.css";

/* ------------------------------------------------------------------ */
/* Constants */
/* ------------------------------------------------------------------ */
const TOKEN = (window as any).g_ck;
const TABLE_API = "/api/now/table";
const SIM_API = "/api/x_2056099_indust_0/operator_api/simulate-whatif";

const SCENARIO_OPTIONS = [
 { value: "", label: "— Select a scenario type —" },
 { value: "resource_down", label: "Resource Down" },
 { value: "capacity_reduction", label: "Capacity Reduction" },
 { value: "quantity_change", label: "Order Quantity Change" },
 { value: "material_shortage", label: "Material Shortage" },
 { value: "schedule_shift", label: "Schedule Shift" },
];

/* ------------------------------------------------------------------ */
/* Helpers */
/* ------------------------------------------------------------------ */

/** Extract display value from a field that may be a plain string or
 * a { display_value, value } object (sysparm_display_value=all). */
function dv(field: any): string {
 if (field == null) return "";
 if (typeof field === "object" && field.display_value !== undefined)
 return String(field.display_value);
 return String(field);
}

/** Fetch records from a ServiceNow table via Table API. */
async function fetchTable(
 table: string,
 query: string,
 fields: string,
): Promise<any[]> {
 const url =
 `${TABLE_API}/${table}` +
 `?sysparm_fields=${fields}` +
 `&sysparm_display_value=all` +
 `&sysparm_query=${encodeURIComponent(query)}`;
 const res = await fetch(url, {
 headers: { "X-UserToken": TOKEN, Accept: "application/json" },
 });
 const data = await res.json();
 return data.result || [];
}

/* ------------------------------------------------------------------ */
/* Component */
/* ------------------------------------------------------------------ */
export default function App() {
 /* ---------- data state ---------- */
 const [resources, setResources] = useState<any[]>([]);
 const [orders, setOrders] = useState<any[]>([]);
 const [schedules, setSchedules] = useState<any[]>([]);
 const [materials, setMaterials] = useState<any[]>([]);
 const [loading, setLoading] = useState(true);
 const [loadError, setLoadError] = useState("");

 /* ---------- form state ---------- */
 const [scenarioType, setScenarioType] = useState("");
 const [targetResourceId, setTargetResourceId] = useState("");
 const [durationDays, setDurationDays] = useState<number>(3);
 const [capacityReductionPct, setCapacityReductionPct] = useState<number>(30);
 const [targetOrderId, setTargetOrderId] = useState("");
 const [newQuantity, setNewQuantity] = useState<number>(500);
 const [materialProductId, setMaterialProductId] = useState("");
 const [shortagePct, setShortagePct] = useState<number>(50);
 const [targetScheduleId, setTargetScheduleId] = useState("");
 const [shiftDays, setShiftDays] = useState<number>(5);

 /* ---------- simulation state ---------- */
 const [simulating, setSimulating] = useState(false);
 const [results, setResults] = useState<any>(null);
 const [simError, setSimError] = useState("");

 /* ---------- load data on mount ---------- */
 useEffect(() => {
 loadAllData();
 }, []);

 async function loadAllData() {
 setLoading(true);
 setLoadError("");
 try {
 const [res, ord, sch, mat] = await Promise.all([
 fetchTable(
 "x_2056099_indust_0_prod_res",
 "active=true",
 "sys_id,resource_name,status,capacity_per_day",
 ),
 fetchTable(
 "x_2056099_indust_0_production_order",
 "active=true^statusNOT INcompleted,cancelled",
 "sys_id,number,status,quantity_planned,finished_product",
 ),
 fetchTable(
 "x_2056099_indust_0_prod_sched",
 "active=true^statusINdraft,scheduled,confirmed,in_progress",
 "sys_id,number,production_order,production_resource,planned_start,planned_end,status",
 ),
 fetchTable(
 "x_2056099_indust_0_mat_master",
 "active=true",
 "sys_id,material_name",
 ),
 ]);
 setResources(res);
 setOrders(ord);
 setSchedules(sch);
 setMaterials(mat);
 } catch (e: any) {
 setLoadError(e.message || "Failed to load production data");
 } finally {
 setLoading(false);
 }
 }

 /* ---------- form helpers ---------- */

 function buildBody(): Record<string, any> | null {
 switch (scenarioType) {
 case "resource_down":
 return {
 scenario_type: scenarioType,
 target_resource_id: targetResourceId,
 duration_days: durationDays,
 };
 case "capacity_reduction":
 return {
 scenario_type: scenarioType,
 target_resource_id: targetResourceId,
 capacity_reduction_pct: capacityReductionPct,
 };
 case "quantity_change":
 return {
 scenario_type: scenarioType,
 target_order_id: targetOrderId,
 new_quantity: newQuantity,
 };
 case "material_shortage":
 return {
 scenario_type: scenarioType,
 material_product_id: materialProductId,
 shortage_pct: shortagePct,
 };
 case "schedule_shift":
 return {
 scenario_type: scenarioType,
 target_schedule_id: targetScheduleId,
 shift_days: shiftDays,
 };
 default:
 return null;
 }
 }

 function canRun(): boolean {
 if (!scenarioType) return false;
 switch (scenarioType) {
 case "resource_down":
 return !!targetResourceId && durationDays > 0;
 case "capacity_reduction":
 return (
 !!targetResourceId &&
 capacityReductionPct >= 1 &&
 capacityReductionPct <= 99
 );
 case "quantity_change":
 return !!targetOrderId && newQuantity > 0;
 case "material_shortage":
 return !!materialProductId && shortagePct >= 1 && shortagePct <= 100;
 case "schedule_shift":
 return !!targetScheduleId && shiftDays !== 0;
 default:
 return false;
 }
 }

 /* ---------- run simulation ---------- */

 async function runSimulation() {
 const body = buildBody();
 if (!body) return;
 setSimulating(true);
 setSimError("");
 setResults(null);
 try {
 const res = await fetch(SIM_API, {
 method: "POST",
 headers: {
 "X-UserToken": TOKEN,
 "Content-Type": "application/json",
 Accept: "application/json",
 },
 body: JSON.stringify(body),
 });
 if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`);
 const data = await res.json();
 if (data.result) {
 setResults(data.result);
 } else {
 setSimError("Unexpected response from simulation API.");
 }
 } catch (e: any) {
 setSimError(e.message || "Simulation request failed.");
 } finally {
 setSimulating(false);
 }
 }

 /* ---------- derived flags ---------- */
 const hasData =
 resources.length > 0 || orders.length > 0 || schedules.length > 0;

 function scenarioLabel(type: string): string {
 const opt = SCENARIO_OPTIONS.find((o) => o.value === type);
 return opt ? opt.label : type;
 }

 /* ================================================================ */
 /* RENDER */
 /* ================================================================ */
 return (
 <div className="wf-shell">
 {/* ---- HEADER ---- */}
 <header className="wf-header">
 <h1 className="wf-header-title">What-If Planner</h1>
 <p className="wf-header-sub">
 Digital Twin — Non-Destructive Simulation
 </p>
 </header>

 <div className="wf-content">
 {/* ---- LOADING ---- */}
 {loading && (
 <div className="wf-loading">Loading production data…</div>
 )}

 {/* ---- LOAD ERROR ---- */}
 {loadError && <div className="wf-error">{loadError}</div>}

 {/* ---- EMPTY STATE (no production data at all) ---- */}
 {!loading && !loadError && !hasData && (
 <div className="wf-empty">
 No production data available. Create production resources, orders,
 and schedules to use the What-If Planner.
 </div>
 )}

 {/* ---- MAIN CONTENT (only when data exists) ---- */}
 {!loading && !loadError && hasData && (
 <>
 {/* ======== CURRENT STATE PANEL ======== */}
 <h2 className="wf-section-title">Current Production State</h2>
 <div className="wf-cards">
 <div className="wf-card">
 <div className="wf-card-value">{resources.length}</div>
 <div className="wf-card-label">Total Resources</div>
 </div>
 <div className="wf-card">
 <div className="wf-card-value">{schedules.length}</div>
