 <div className="wf-card-label">Active Orders</div>
 </div>
 </div>

 {/* ======== SCENARIO BUILDER ======== */}
 <h2 className="wf-section-title">Scenario Builder</h2>
 <div className="wf-form">
 {/* Scenario type selector */}
 <div className="wf-form-field">
 <label>Scenario Type</label>
 <select
 className="wf-input"
 value={scenarioType}
 onChange={(e) => {
 setScenarioType(e.target.value);
 setResults(null);
 setSimError("");
 }}
 >
 {SCENARIO_OPTIONS.map((o) => (
 <option key={o.value} value={o.value}>
 {o.label}
 </option>
 ))}
 </select>
 </div>

 {/* ---- Resource Down fields ---- */}
 {scenarioType === "resource_down" && (
 <>
 <div className="wf-form-field">
 <label>Resource</label>
 <select
 className="wf-input"
 value={targetResourceId}
 onChange={(e) => setTargetResourceId(e.target.value)}
 >
 <option value="">— Select resource —</option>
 {resources.map((r) => (
 <option key={r.sys_id} value={r.sys_id}>
 {dv(r.resource_name)} ({dv(r.status)})
 </option>
 ))}
 </select>
 </div>
 <div className="wf-form-field">
 <label>Duration (days)</label>
 <input
 className="wf-input"
 type="number"
 min={1}
