 onChange={(e) =>
 setDurationDays(parseInt(e.target.value) || 0)
 }
 />
 </div>
 </>
 )}

 {/* ---- Capacity Reduction fields ---- */}
 {scenarioType === "capacity_reduction" && (
 <>
 <div className="wf-form-field">
