 </td>
 <td>
 <span className="wf-badge wf-badge-warn">{p.delay_before_adaptation}d</span>
 </td>
 <td>
 <span className={`wf-badge ${p.delay_after_adaptation > 0 ? "wf-badge-warn" : "wf-badge-ok"}`}>
 {p.delay_after_adaptation}d
 </span>
 </td>
 <td>
 {p.delay_recovered > 0 ? (
 <span className="wf-badge wf-badge-ok">↓ {p.delay_recovered}d</span>
 ) : "—"}
 </td>
 <td>
 {p.feasible ? (
 <span className="wf-badge wf-badge-ok">Reassigned</span>
 ) : (
 <span className="wf-badge wf-badge-warn">No alternative</span>
 )}
 </td>
 </tr>
 ))}
 </tbody>
 </table>
 </div>
 {results.adaptiveProposals.some((p: any) => !p.feasible) && (
 <div className="wf-detail-reasons">
 <h3 className="wf-section-title">Unrecoverable Schedules</h3>
 {results.adaptiveProposals.filter((p: any) => !p.feasible).map((p: any, i: number) => (
 <div key={i} className="wf-reason-row">
 <strong>{p.schedule_number}</strong> ({p.order_display}): {p.reason}
 </div>
 ))}
 </div>
 )}
 </>
 )}

 {/* Closing sim disclaimer */}
 <div className="wf-sim-footer">
 This is a simulation only. No changes have been made to
 production data.
 </div>
 </div>
 )}
 </>
 )}
 </div>
 </div>
 );
}
